contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 betAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (betAmount)); require(betAmount <= 1000000000000000000000000000000);
        require(betAmount == c.currentBetLimit(), "bet must equal current bet limit");
        require(address(this).balance >= betAmount, "insufficient balance");

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.wager{value: betAmount}(); if (__ESBMC_reverted()) return;

        bool playReverted;
        c.play(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            playReverted = true;
        } else {
            playReverted = false;
        }

        bool wageredAfter = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        assert(!wageredAfter == playReverted);
    }

    receive() external payable {}
}

