    }

    function _run(uint256 betAmount) internal {
        betAmount = bound(betAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        betAmount = c.currentBetLimit();
        vm.assume(address(this).balance >= betAmount);
        try c.OpenToThePublic() {} catch { return; }
        try c.wager{value: betAmount}() {} catch { return; }
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        bool wageredAfter;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { wageredAfter = __r; } catch { return; }
        assertTrue(!wageredAfter == playReverted);
    }

    function testFuzz_run(uint256 betAmount) public {
        _run(betAmount);
    }

    receive() external payable {}
}
